use hec_native_ic::{counted,fp::Fp,poly::Poly,instance::pick_instance};
const PAIRS:[(usize,usize);6]=[(0,1),(0,2),(0,3),(1,2),(1,3),(2,3)];
fn nullspace(mut m:Vec<Vec<u64>>,f:&Fp)->(usize,Vec<Vec<u64>>){let mut pivots=vec![];let mut row=0;for j in 0..6{let Some(at)=(row..m.len()).find(|&i|m[i][j]!=0)else{continue;};m.swap(row,at);let inv=f.inv(m[row][j]);for x in &mut m[row]{*x=f.mul(*x,inv);}for i in 0..m.len(){if i==row||m[i][j]==0{continue;}let a=m[i][j];for k in 0..6{m[i][k]=f.sub(m[i][k],f.mul(a,m[row][k]));}}pivots.push(j);row+=1;}let mut basis=vec![];for free in 0..6{if pivots.contains(&free){continue;}let mut v=vec![0;6];v[free]=1;for(i,&p)in pivots.iter().enumerate(){v[p]=f.neg(m[i][free]);}basis.push(v);} (row,basis)}
fn dot(a:&[u64],b:&[u64],f:&Fp)->u64{a.iter().zip(b).fold(0,|s,(&a,&b)|f.add(s,f.mul(a,b)))}
fn phi(w:&[u64],f:&Fp)->u64{f.add(f.sub(f.mul(w[0],w[5]),f.mul(w[1],w[4])),f.mul(w[2],w[3]))}
fn canonical(mut w:Vec<u64>,f:&Fp)->Vec<u64>{let x=w.iter().copied().find(|&x|x!=0).unwrap();let inv=f.inv(x);for v in &mut w{*v=f.mul(*v,inv);}w}
fn rational_points(basis:&[Vec<u64>],f:&Fp)->Vec<Vec<u64>>{assert_eq!(basis.len(),2);let mut out=std::collections::BTreeSet::new();for t in 0..f.p{let w:Vec<_>=basis[0].iter().zip(&basis[1]).map(|(&a,&b)|f.add(a,f.mul(t,b))).collect();if phi(&w,f)==0{out.insert(canonical(w,f));}}if phi(&basis[1],f)==0{out.insert(canonical(basis[1].clone(),f));}out.into_iter().collect()}
fn wedge(w:&[u64],i:usize,j:usize,f:&Fp)->u64{if i==j{0}else if i<j{w[PAIRS.iter().position(|&p|p==(i,j)).unwrap()]}else{f.neg(wedge(w,j,i,f))}}
fn recover(w:&[u64],f:&Fp)->(Poly,Poly){assert_eq!(phi(w,f),0);let at=w.iter().position(|&x|x!=0).unwrap();let(i,j)=PAIRS[at];let inv=f.inv(w[at]);let mut n=vec![0;4];let mut d=vec![0;4];for k in 0..4{n[k]=f.neg(f.mul(wedge(w,j,k,f),inv));d[k]=wedge(w,i,k,f);}for(at,&(i,j))in PAIRS.iter().enumerate(){assert_eq!(f.sub(f.mul(n[i],d[j]),f.mul(n[j],d[i])),w[at]);}(Poly::from_coeffs(&n),Poly::from_coeffs(&d))}
fn compose(a:&Poly,h:&Poly,q:&Poly,f:&Fp)->Poly{let mut out=Poly::zero();for i in(0..a.n).rev(){out=out.mulmod(h,q,f).add(&Poly::constant(a.c[i]),f);}out}
fn identifies(n:&Poly,d:&Poly,r:u64,h:&Poly,q:&Poly,f:&Fp)->bool{if n.deg().max(d.deg())!=3||Poly::gcd(n,d,f).deg()!=0{return false;}if f.sub(f.mul(n.eval(r,f),d.c[3]),f.mul(n.c[3],d.eval(r,f)))!=0{return false;}n.mulmod(&compose(d,h,q,f),q,f).sub(&d.mulmod(&compose(n,h,q,f),q,f),f).is_zero()}
fn controls(){let f=Fp::new(101);let n1=Poly::from_coeffs(&[1,1,0,1]);let d1=Poly::from_coeffs(&[1,0,1]);let n2=Poly::from_coeffs(&[1,2,0,1]);let d2=Poly::from_coeffs(&[2,0,1]);let ws=|n:&Poly,d:&Poly|PAIRS.iter().map(|&(i,j)|f.sub(f.mul(n.c[i],d.c[j]),f.mul(n.c[j],d.c[i]))).collect::<Vec<_>>();let a=canonical(ws(&n1,&d1),&f);let b=canonical(ws(&n2,&d2),&f);let(_,matrix)=nullspace(vec![a.clone(),b.clone()],&f);let(rank,basis)=nullspace(matrix.clone(),&f);assert_eq!(rank,4);let roots=rational_points(&basis,&f);assert_eq!(roots.len(),2);assert!(roots.contains(&a)&&roots.contains(&b));for w in roots{assert!(matrix.iter().all(|r|dot(r,&w,&f)==0));let(n,d)=recover(&w,&f);assert_eq!(Poly::gcd(&n,&d,&f).deg(),0);assert_eq!(n.deg().max(d.deg()),3);}assert_eq!(f.legendre(2),-1);let a=vec![1,0,0,0,0,1];let b=vec![0,1,0,0,2,0];assert!(rational_points(&[a,b],&f).is_empty());eprintln!("CONTROL split_line_two_maps=true anisotropic_line_no_points=true wedge_reconstruction=true");}
fn main(){counted::disable();controls();let mut cases=0;let mut unsupported=0;for line in include_str!("../native-pencil-3lp/INSTANCES.tsv").lines().skip(1){let v:Vec<_>=line.split('\t').collect();if v[0]!="3"{continue;}let p:u64=v[1].parse().unwrap();let inst=pick_instance(p,3).unwrap();assert_eq!(inst.c.to_string(),v[2]);assert_eq!(inst.ell.to_string(),v[3]);let c=inst.curve;let f=&c.fp;assert_eq!(c.f.c[..c.f.n].iter().map(u64::to_string).collect::<Vec<_>>().join(","),v[4]);let roots:Vec<_>=(0..p).filter(|&x|c.f.eval(x,f)==0).collect();assert_eq!(roots.len(),1);let r=roots[0];let q=c.f.div_exact(&Poly::x_minus(r,f),f);assert_eq!(q.deg(),6);let mut xp=Poly::x();let mut h=Poly::zero();for i in 1..=6{xp=xp.powmod(p,&q,f);if i<=3{assert_eq!(Poly::gcd(&q,&xp.sub(&Poly::x(),f),f).deg(),0);}if i==3{h=xp;}}assert_eq!(xp,Poly::x());assert_eq!(compose(&h,&h,&q,f),Poly::x());assert_eq!(Poly::gcd(&q,&h.sub(&Poly::x(),f),f).deg(),0);
let mut xs=vec![Poly::one()];let mut hs=vec![Poly::one()];for i in 1..4{xs.push(xs[i-1].mulmod(&Poly::x(),&q,f));hs.push(hs[i-1].mulmod(&h,&q,f));}let columns:Vec<_>=PAIRS.iter().map(|&(i,j)|xs[i].mulmod(&hs[j],&q,f).sub(&xs[j].mulmod(&hs[i],&q,f),f)).collect();let mut matrix:Vec<Vec<u64>>=(0..6).map(|k|columns.iter().map(|c|c.c[k]).collect()).collect();let mut infinity=vec![0;6];for(at,&(i,j))in PAIRS.iter().enumerate(){if j==3{infinity[at]=f.pow(r,i as u64);}}matrix.push(infinity);let(rank,basis)=nullspace(matrix.clone(),f);cases+=1;if basis.len()!=2{println!("CASE p={p} c={} root={r} matrix_rank={rank} status=UNSUPPORTED_NULLITY basis={basis:?}",inst.c);unsupported+=1;continue;}for b in &basis{assert!(matrix.iter().all(|r|dot(r,b,f)==0));}let qa=phi(&basis[0],f);let qc=phi(&basis[1],f);let sum:Vec<_>=basis[0].iter().zip(&basis[1]).map(|(&a,&b)|f.add(a,b)).collect();let qb=f.sub(f.sub(phi(&sum,f),qa),qc);let disc=f.sub(f.mul(qb,qb),f.mul(4,f.mul(qa,qc)));let roots=rational_points(&basis,f);if qc!=0{assert_eq!(roots.len(),(1+f.legendre(disc))as usize);}else if qb!=0{assert_eq!(roots.len(),2);}else if qa!=0{assert_eq!(roots.len(),1);}else{assert_eq!(roots.len(),p as usize+1);}let mut maps=0;let mut degenerate=0;for w in &roots{assert!(matrix.iter().all(|r|dot(r,w,f)==0));let(n,d)=recover(w,f);if !identifies(&n,&d,r,&h,&q,f){degenerate+=1;println!("DEGENERATE p={p} wedge={w:?} n={:?} d={:?}",&n.c[..n.n],&d.c[..d.n]);continue;}let mut rejected=false;for i in 0..4{let mut coeff=n.c[..4].to_vec();coeff[i]=f.add(coeff[i],1);if !identifies(&Poly::from_coeffs(&coeff),&d,r,&h,&q,f){rejected=true;break;}}assert!(rejected,"mutation control must reject");println!("MAP p={p} c={} wedge={w:?} numerator={:?} denominator={:?} rational_pair_identity=true degree=3 coprime=true mutation_rejected=true",inst.c,&n.c[..n.n],&d.c[..d.n]);maps+=1;}println!("CASE p={p} c={} ell={} root={r} sextic={:?} conjugation={:?} matrix_rank={rank} basis={basis:?} quadric=[{qa},{qb},{qc}] discriminant={disc} discriminant_legendre={} projective_roots={} degenerate={degenerate} rational_degree3_maps={maps}",inst.c,inst.ell,&q.c[..q.n],&h.c[..h.n],f.legendre(disc),roots.len());}
assert_eq!(cases,3);eprintln!("PASS cases=3 unsupported={unsupported} exact_sextic_frobenius=true projective_line_exhausted=true actual_maps_verified=true no_quotient_or_transport_or_speed_claim=true");if unsupported>0{std::process::exit(2);}}
